\label{tab:power_benchmarks}
\begin{tabular}{lcccc}
\toprule
\textbf{Benchmark} & $n$ & \textbf{Theory} & \textbf{Adjusted} & $|d|$ \\
\midrule
MMLU & 14,042 & 0.98 & 0.65 & 2.8 \\
HellaSwag & 10,042 & 0.75 & 0.45 & 1.0 \\
BBH & 6,511 & 0.42 & 0.18 & 0.5 \\
MATH & 5,000 & 0.35 & 0.12 & 0.3 \\
